def matchup_channels(t: torch.Tensor, w: torch.Tensor):
    # Ensure t and w have the same number of channels
    if t.shape[-1] != w.shape[-1]:
        # Expand the shorter tensor to match the longer one
        if t.shape[-1] < w.shape[-1]:
            t = torch.cat([t, torch.zeros_like(t[..., -1:])], dim=-1)
        else:
            w = torch.cat([w, torch.zeros_like(w[..., -1:])], dim=-1)
    return t, w
